    // it is transparent. A terrain's color map cuts its holes here.
    float alpha = (flags & kHasAlpha) != 0u ? color.a : 1.0;
    if ((flags & kAlphaScissor) != 0u) {
        if (alpha < asfloat(options.y)) {
            discard;
        }
        alpha = 1.0;
    }
