    // and their direct light by its light affect times its AO channel affect. Its SSR (alpha
    // below 0 for none) goes over their reflections of the sky.
    float ao = 1.0;
    float ao_direct = 1.0;
    float4 ssr = float4(0.0, 0.0, 0.0, -1.0);
